FILES = {'app/sources/gpb/relevance.py': {'before': '87244cb0ddc6b032b831277288a52509bf136693eb4fbd8a822fd9b11bceabc6', 'text': '"""GPB subject gate v2: explicit non-targets only; no implied LLM approval."""\nimport re\nimport unicodedata\nVERSION = \'gpb-positive-20261019-v3\'\n\n\ndef norm(value):\n    return \' \'.join(unicodedata.normalize(\'NFKC\',str(value or \'\')).casefold().replace(\'ё\',\'е\').split())\n\nPRODUCT = re.compile(r\'\\b(?:лист(?:ы|а|ов|ам|ами|ах)?|лент\\w*|плит\\w*|полос\\w*|труб\\w*|профил\\w*|прут\\w*|шин(?:а|ы|у|ой|ами)?|катанк\\w*|проволок\\w*|фольг\\w*|рулон\\w*|штрипс\\w*|прокат\\w*|поков\\w*|заготов\\w*|слит\\w*|чушк\\w*)\\b\')\nALUMINIUM = re.compile(r\'\\bалюмини\\w*|\\b(?:амг\\s*\\d\\w*|амц\\w*|ад\\s*(?:00|0|1|31|33)\\w*|д(?:1|16|19)\\w*|в95\\w*|вд1\\w*|ак[46](?:[- ]1)?\\w*|а[0567](?:е)?|1561\\w*|1105\\w*)\\b\')\nOTHER_METAL = re.compile(r\'\\b(?:сталь|стали|сталью|сталям\\w*|стальн\\w*|нержав\\w*|сталь20|ст20|ст3|09г2с|12х18н10т|08х18н10|медн\\w*|медь|меди|латун\\w*|бронз\\w*|чугун\\w*)\\b\')\nFINISHED = re.compile(r\'\\b(?:стул(?:а|у|ом|е|ья|ьев|ьям|ьями|ьях)?|стуль\\w*|стол(?:а|у|ом|е|ы|ов|ам|ами|ах)?|кресл\\w*|мебел\\w*|табурет\\w*|диван\\w*|скаме\\w*|шкаф\\w*|светильник\\w*|грабл\\w*|канистр\\w*|перчат\\w*|стремянк\\w*|лестниц\\w*|кастрюл\\w*|сковород\\w*|посуд\\w*|листогибочн\\w*|листоправильн\\w*|станк\\w*|лекарственн\\w*|сульфат\\w*|хлорид\\w*)\\b\')\nSERVICE = re.compile(r\'^(?:(?:право заключения договора на|закупка|поставка|приобретение)\\s+)?(?:выполнени\\w*\\s+работ\\w*|оказани\\w*\\s+услуг\\w*|ремонт\\w*|обслуживани\\w*|монтаж\\w*|демонтаж\\w*|реализаци\\w*|продаж\\w*)\\b\')\n\n\ndef clause_class(value):\n    text=norm(value)\n    # Remove a leading reference, never the words describing the purchased object.\n    text=re.sub(r\'^\\d[\\d/._-]*\\s*[-:.)]?\\s+\',\'\',text)\n    p=PRODUCT.search(text);f=FINISHED.search(text)\n    if SERVICE.search(text):return \'non_target\'\n    if f and (p is None or f.start()<=p.start()):return \'non_target\'\n    if OTHER_METAL.search(text) and not ALUMINIUM.search(text):return \'non_target\'\n    if p and ALUMINIUM.search(text):\n        # E.g. aluminium and steel in one unsplit description needs positions.\n        return \'uncertain\' if OTHER_METAL.search(text) else \'target_product\'\n    return \'uncertain\'\n\n\ndef text_class(value):\n    text=norm(value)\n    parts=re.split(r\';|\\n|\\s+и\\s+|,\\s*(?=(?:стул|кресл|лист|лент|труб|профил|прут|фольг|поставка))\',text)\n    kinds=[clause_class(part) for part in parts if part.strip()]\n    if \'target_product\' in kinds:return \'target_product\'\n    if kinds and all(k==\'non_target\' for k in kinds):return \'non_target\'\n    # Generic tails like "для офиса", kept in the same clause, don\'t rescue furniture.\n    return \'uncertain\'\n\n\ndef screen(item):\n    raw=item.get(\'raw_payload\') or {}\n    positions=raw.get(\'positions\') or []\n    kinds=[];missing=False\n    if isinstance(positions,list):\n        for p in positions:\n            if not isinstance(p,dict):missing=True;continue\n            title=p.get(\'name\') or p.get(\'title\') or p.get(\'product_name\')\n            if not isinstance(title,str) or not title.strip():missing=True;continue\n            kinds.append(text_class(title))\n    state=text_class(item.get(\'title\'))\n    # Public rows may be incomplete: retain uncertainty rather than silently losing a mixed lot.\n    if \'target_product\' in kinds:state=\'target_product\'\n    elif missing or \'uncertain\' in kinds:state=\'uncertain\'\n    elif kinds and all(k==\'non_target\' for k in kinds):\n        state=\'uncertain\' if state==\'target_product\' else \'non_target\'\n    reason={\'non_target\':\'Нецелевой предмет: мебель, готовое изделие, оборудование, работы либо явно неалюминиевый материал.\',\n            \'target_product\':\'Есть признаки алюминиевого материала; спецификация и масса от 500 кг по позиции ещё требуют проверки.\',\n            \'uncertain\':\'Материал или состав закупки не подтверждён; требуется проверить позиции и спецификацию.\'}[state]\n    return {\'version\':VERSION,\'classification\':state,\'action\':{\'non_target\':\'reject\',\'uncertain\':\'hold\',\'target_product\':\'review\'}[state],\'reason\':reason}\n\n\ndef blocked_item(item):\n    if item.get(\'source\')!=\'gpb\':return None\n    result=screen(item)\n    if result[\'action\']==\'review\':return None\n    return {\'status\':\'skipped\',\'reason\':\'gpb_non_target_subject\' if result[\'action\']==\'reject\' else \'gpb_product_unconfirmed\',\'external_id\':str(item.get(\'external_id\') or \'\'),\n            \'screening_version\':VERSION,\'details\':result[\'reason\']}\n\n\ndef blocked_tender(tender):\n    if tender is None:return None\n    result=blocked_item({\'source\':tender.source,\'external_id\':tender.external_id,\n                         \'title\':tender.title,\'raw_payload\':tender.raw_payload})\n    if result:result[\'tender_id\']=str(tender.id)\n    return result\n'}, 'app/reports/review_dashboard.py': {'before': '59b36f1e8b6156b11cae3381748861c619296e3eb2c329c9841b6a48aad533fb', 'text': '"""Read-only review inbox: DB tenders and marketplace candidates."""\nfrom datetime import datetime, timezone\nfrom sqlalchemy import select, or_\nfrom app.db.session import SyncSessionLocal\nfrom app.models.database import Tender, Decision, TenderStatus, ProcessingStatus\nfrom app.marketplace_discovery.review_store import list_review_candidates\nfrom app.marketplace_discovery.product_screening import screen_candidate\n\n\ndef assemble(rows, candidates, now=None):\n    now = now or datetime.now(timezone.utc)\n    merged = {}\n    for row in list(rows) + list(candidates):\n        row = dict(row)\n        key = (row.get(\'source\'), str(row.get(\'external_id\') or \'\'))\n        if not all(key) or key in merged:\n            continue\n        deadline = row.get(\'submission_deadline\')\n        try:\n            dt = datetime.fromisoformat(str(deadline).replace(\'Z\', \'+00:00\')) if deadline else None\n            if dt and dt.tzinfo is None: dt = dt.replace(tzinfo=timezone.utc)\n        except ValueError:\n            dt = None\n        if dt is None or dt <= now: continue\n        row[\'submission_deadline\'] = dt.isoformat() if dt else None\n        row[\'deadline_unknown\'] = dt is None\n        merged[key] = row\n    return sorted(merged.values(), key=lambda r: (r[\'deadline_unknown\'], r[\'submission_deadline\'] or \'\', r.get(\'title\') or \'\'))\n\n\ndef get_review_dashboard():\n    rows=[]\n    gpb_details={}\n    with SyncSessionLocal() as s:\n        tenders=s.execute(select(Tender).where(Tender.is_active.is_(True),\n            or_(Tender.status.in_([TenderStatus.MANUAL_REVIEW, TenderStatus.NEEDS_CLARIFICATION]),\n                Tender.processing_status.in_([ProcessingStatus.FAILED,ProcessingStatus.DOCUMENTS_PENDING,ProcessingStatus.INGESTED,ProcessingStatus.DOCUMENTS_READY,ProcessingStatus.ANALYZING])))).scalars().all()\n        ids=[t.id for t in tenders]\n        decisions={}\n        if ids:\n            for d in s.execute(select(Decision).where(Decision.tender_id.in_(ids)).order_by(Decision.created_at.desc())).scalars():\n                decisions.setdefault(str(d.tender_id), d)\n        for t in tenders:\n            raw=t.raw_payload or {}\n            if t.source == \'gpb\': gpb_details[t.external_id] = raw\n            from app.sources.eis_freshness import eligibility\n            if eligibility(t.source, t.submission_deadline, raw, t.is_active) is not None:\n                continue\n            # Explicit title-based exclusions are not pending specification checks.\n            if (raw.get(\'subject_screening\') or {}).get(\'subject_type\') in (\'works_service\',\'finished_product\'):continue\n            if t.source == \'b2b_center\':\n                screening=screen_candidate({\'source\':t.source,\'external_id\':t.external_id,\n                    \'title\':t.title,\'submission_deadline\':t.submission_deadline,\n                    \'is_active\':t.is_active,\'raw_payload\':raw})\n                if screening[\'action\']==\'reject\': continue\n            if t.source == \'gpb\':\n                # GPB subject v2 also hides previously failed/manual-review records.\n                from app.sources.gpb.relevance import screen\n                if screen({\'title\':t.title,\'raw_payload\':raw})[\'action\'] != \'review\':continue\n            d=decisions.get(str(t.id))\n            rows.append({\'source\':t.source,\'external_id\':t.external_id,\'title\':t.title,\n                \'source_url\':t.source_url,\'submission_deadline\':t.submission_deadline,\n                \'status\':getattr(t.status,\'value\',t.status),\n                \'analysis_done\':bool(t.analysis_done),\n                 \'reason\': (\'Ошибка обработки: требуется проверка исходных данных\' if t.processing_status == ProcessingStatus.FAILED\n                    else (\'; \'.join(str(x) for x in (d.reasons or [])) if d and t.analysis_done else \'Ожидается завершение автоматической обработки\'))})\n    from app.reports.gpb_dashboard import list_candidates, document_reason\n    for row in rows:\n        if row.get(\'source\') == \'gpb\':\n            row[\'reason\'] = document_reason(gpb_details.get(row[\'external_id\'], {}), row[\'reason\'])\n    candidates=list_candidates()\n    for c in list_review_candidates(500):\n        if c.get(\'source\') == \'gpb\':\n            from app.sources.gpb.relevance import screen\n            if screen(c)[\'action\'] != \'review\':\n                continue\n        screening=screen_candidate(c) if c.get(\'source\')==\'b2b_center\' else None\n        if screening and screening[\'action\']==\'reject\': continue\n        candidates.append({\'source\':c.get(\'source\'),\'external_id\':c.get(\'external_id\'),\n            \'title\':c.get(\'title\'),\'source_url\':c.get(\'source_url\'),\n            \'submission_deadline\':c.get(\'submission_deadline\'),\'status\':\'candidate\',\n            \'analysis_done\':False,\'reason\':(screening[\'message\'] if screening else None) or (c.get(\'raw_payload\') or {}).get(\'review_reason\') or \'Кандидат площадки: требуется подтвердить позиции и объём; полный анализ не выполнен\'})\n    from app.reports.review_dismissals import is_dismissed\n    items=[r for r in assemble(rows,candidates) if not is_dismissed(r["source"], r["external_id"])]\n    return {\'count\':len(items),\'tenders\':items,\'candidate_limit\':500}\n'}, 'app/reports/gpb_dashboard.py': {'before': 'e1805780c5467a1352d467e5e2764bd413a2f93b383a1f7ec46e081e28b86dca', 'text': '"""Expose pending GPB candidates in existing review inbox, read-only."""\nimport json\nimport sqlite3\nfrom pathlib import Path\nfrom datetime import datetime,timezone\n\n\ndef candidates_from_file(path, now=None):\n    now=now or datetime.now(timezone.utc)\n    path=Path(path)\n    if not path.exists():return []\n    with sqlite3.connect(path.resolve().as_uri()+\'?mode=ro\',uri=True,timeout=5) as db:\n        data=db.execute(\'SELECT payload FROM pending ORDER BY deadline,number LIMIT 500\').fetchall()\n    from app.sources.gpb.relevance import screen\n    result=[]\n    from app.sources.gpb.adapter import identity\n    from app.sources.gpb.card import deadline\n    for (payload,) in data:\n        try:\n            item=json.loads(payload);identity(item)\n            if screen(item)[\'action\'] != \'review\':continue\n            end=deadline(item.get(\'submission_deadline\'))\n            if end is None or end<=now:continue\n            result.append({**item,\'source\':\'gpb\',\'status\':\'candidate\',\'analysis_done\':False,\n                \'raw_payload\':{\'stage\':\'search\',\'procurement_status\':\'Прием заявок\'},\n                \'reason\':\'ГПБ: ожидает проверки позиций и документов. Пригодность и масса от 500 кг по отдельной позиции ещё не подтверждены.\'})\n        except (ValueError,TypeError,KeyError):continue\n    return result\n\n\ndef list_candidates():\n    from app.core.config import settings\n    from app.db.session import SyncSessionLocal\n    from app.models.database import Tender\n    from sqlalchemy import select\n    from app.reports.review_dismissals import is_dismissed\n    rows=candidates_from_file(Path(settings.storage_path)/\'gpb_backlog.sqlite3\')\n    if not rows:return []\n    # Existing DB row owns status; do not resurrect rejected/completed rows as candidates.\n    with SyncSessionLocal() as session:\n        existing=set(session.execute(select(Tender.external_id).where(\n            Tender.source==\'gpb\',Tender.external_id.in_([r[\'external_id\'] for r in rows]))).scalars())\n    return [r for r in rows if r[\'external_id\'] not in existing and not is_dismissed(\'gpb\',r[\'external_id\'])]\n\n\ndef document_reason(raw, fallback):\n    state=(raw or {}).get(\'gpb_documents\') or {}\n    if not state or state.get(\'complete\') is True:return fallback\n    docs=state.get(\'documents\') or [];errors=state.get(\'errors\') or []\n    names=\'; \'.join(str(x.get(\'name\') or \'без имени\') for x in errors[:3])\n    return (\'ГПБ: неполный комплект документов. Получено: \'+str(len(docs))+\n            \', ошибок: \'+str(len(errors))+\'. Анализ не завершён.\'+\n            (\' Недоступны: \'+names if names else \'\'))\n'}, 'app/sources/gpb/dispatch.py': {'before': '304cd8869d21c6ec47ad36e36f96470a3a052bb00d8a4226b3dfa51133d695c9', 'text': '"""Canonical-source deduplication before HTTP and bounded automatic handoff."""\nfrom datetime import datetime,timezone\nfrom .adapter import identity,resolve\nfrom app.sources.tektorg.backlog import deadline,process_backlog\nfrom app.reports.review_dismissals import is_dismissed\n\n\ndef enqueue_candidates(items):\n    import redis\n    from sqlalchemy import select\n    from app.core.config import settings\n    from app.db.session import SyncSessionLocal\n    from app.models.database import Tender\n    from app.workers.completed_analysis import has_completed_analysis\n    from app.workers.tasks_parsing import process_new_tender\n    client=redis.Redis.from_url(settings.redis_url)\n    from app.sources.gpb.relevance import screen\n    results=[];attempts=0\n    for item in items:\n        number=str(item.get(\'external_id\',\'\'))\n        row={\'number\':number}\n        try:\n            end=deadline(item)\n            if end is None or end<=datetime.now(timezone.utc):\n                results.append(dict(row,status=\'no_longer_eligible\'));continue\n            source,canonical=identity(item)\n            row.update(canonical_source=source,canonical_number=canonical)\n            if is_dismissed(\'gpb\',number) or is_dismissed(source,canonical):\n                results.append(dict(row,status=\'no_longer_eligible\'));continue\n            with SyncSessionLocal() as session:\n                tender=session.execute(select(Tender).where(Tender.source==source,Tender.external_id==canonical)).scalar_one_or_none()\n                if tender and has_completed_analysis(session,tender):\n                    results.append(dict(row,status=\'cached\'));continue\n                if tender and not tender.is_active:\n                    results.append(dict(row,status=\'no_longer_eligible\'));continue\n                if tender and getattr(tender.processing_status,\'value\',tender.processing_status) in (\'analyzing\',\'documents_pending\'):\n                    results.append(dict(row,status=\'in_progress\'));continue\n            screening=screen(item)\n            if screening[\'action\']==\'reject\':\n                results.append(dict(row,status=\'no_longer_eligible\',reason=\'non_target_subject\'));continue\n            if screening[\'action\']==\'hold\':\n                results.append(dict(row,status=\'awaiting_product_confirmation\',reason=\'gpb_product_unconfirmed\'));continue\n            if attempts>=2:\n                results.append(dict(row,status=\'batch_limit\'));continue\n            key=\'gpb:pipeline:v1:\'+source+\':\'+canonical\n            if not client.set(key,\'reserved\',nx=True,ex=86400):\n                results.append(dict(row,status=\'already_queued_or_attempted\'));continue\n            attempts+=1\n            card=resolve(item)\n            if card is None:\n                results.append(dict(row,status=\'no_longer_eligible\'));continue\n            if card.source!=source or str(card.external_id)!=canonical:\n                raise ValueError(\'gpb_resolved_identity_mismatch\')\n            screening=screen({\'title\':card.title,\'raw_payload\':card.raw_payload})\n            if screening[\'action\']==\'reject\':\n                results.append(dict(row,status=\'no_longer_eligible\',reason=\'non_target_positions\'));continue\n            if screening[\'action\']==\'hold\':\n                results.append(dict(row,status=\'awaiting_product_confirmation\',reason=\'gpb_product_unconfirmed\'));continue\n            task=process_new_tender.delay(card.model_dump(mode=\'json\'))\n            results.append(dict(row,status=\'queued\',task_id=task.id))\n        except Exception as exc:\n            results.append(dict(row,status=\'queue_error\',error_type=type(exc).__name__,\n                                reason=str(exc) if isinstance(exc,ValueError) else \'processing_unavailable\'))\n    return results\n\n\ndef drain(items):\n    from pathlib import Path\n    from app.core.config import settings\n    return process_backlog(items,path=Path(settings.storage_path)/\'gpb_backlog.sqlite3\',enqueue=enqueue_candidates)\n'}, 'app/sources/document_preparer.py': {'before': '331d24520b678758ce142dbdaacd54cb4156300acab1a5e82c0bdd87d8261aff', 'text': '"""Prepare source documents for the common tender processing pipeline."""\n\nfrom __future__ import annotations\n\nfrom app.core.logging import get_logger\nfrom app.sources.document_relevance import (\n    rank_documents,\n)\nfrom app.sources.schemas import (\n    SourceDocument,\n    SourceTender,\n)\n\nlogger = get_logger(__name__)\n\n\nSELECTED_TIERS = {\n    "must_download",\n    "high_priority",\n    "secondary",\n}\n\n\ndef _select_documents(\n    documents: list[SourceDocument],\n) -> list[SourceDocument]:\n    """\n    Select technically relevant documents using metadata scoring.\n\n    Preserve original source order after selection.\n    """\n    if not documents:\n        return []\n\n    ranked = rank_documents(documents)\n\n    selected_ids = {\n        id(item.document)\n        for item in ranked\n        if item.tier in SELECTED_TIERS\n    }\n\n    selected = [\n        document\n        for document in documents\n        if id(document) in selected_ids\n    ]\n\n    # Safety fallback:\n    # never silently discard every attachment.\n    if not selected and documents:\n        best = ranked[0] if ranked else None\n\n        if best is not None:\n            selected = [best.document]\n\n    return selected\n\n\ndef prepare_tender_documents(\n    tender: SourceTender,\n) -> list[SourceDocument]:\n    """\n    Convert source-specific attachments into documents consumable\n    by the common OCR/extraction pipeline.\n\n    EIS:\n        metadata selection\n        -> cookie-aware materialization\n        -> local_file SourceDocument\n\n    Other sources:\n        metadata selection\n        -> keep existing SourceDocument contract\n    """\n    if (tender.raw_payload or {}).get(\'multi_pipeline\'):\n        from app.sources.multi_pipeline import prepared_documents\n        return prepared_documents(tender)\n    if tender.source == \'gpb\':\n        from app.sources.gpb.relevance import blocked_item\n        subject_block=blocked_item(tender.model_dump())\n        if subject_block:\n            raise ValueError(subject_block[\'reason\'])\n        from app.sources.gpb.adapter import materialize\n        return materialize(tender)\n    if tender.source == \'metal_it\':\n        from app.sources.metal_it.adapter import materialize\n        return materialize(tender)\n    if tender.source == \'fabrikant\':\n        from app.sources.fabrikant.adapter import materialize\n        return materialize(tender)\n    if tender.source == \'tektorg\':\n        from app.sources.tektorg.adapter import materialize\n        return materialize(tender)\n    if tender.source == \'b2b_center\':\n        from app.marketplace_discovery.b2b_public import prepare_public_snapshot\n        return prepare_public_snapshot(tender)\n    documents = list(tender.documents or [])\n\n    if not documents:\n        logger.info(\n            "no_source_documents",\n            source=tender.source,\n            external_id=tender.external_id,\n        )\n        return []\n\n    # Existing sources keep their current document behaviour.\n    # Do not change Tender.Pro / Kontur processing while\n    # introducing the new EIS transport.\n    if tender.source != "zakupki_gov_ru":\n        return documents\n\n    selected = _select_documents(documents)\n\n    logger.info(\n        "documents_selected",\n        source=tender.source,\n        external_id=tender.external_id,\n        total=len(documents),\n        selected=len(selected),\n        names=[\n            document.name\n            for document in selected\n        ],\n    )\n\n    if not tender.source_url:\n        raise ValueError(\n            "EIS tender source_url is required "\n            "for document materialization"\n        )\n\n    from app.sources.zakupki_gov_public.detail_client import (\n        EisDocumentRef,\n    )\n    from app.sources.zakupki_gov_public.materializer import (\n        materialize_selected_documents,\n    )\n\n    eis_documents = [\n        EisDocumentRef(\n            name=document.name,\n            url=document.url,\n            uid=document.external_id,\n        )\n        for document in selected\n        if document.url\n    ]\n\n    if not eis_documents:\n        return []\n\n    materialized = materialize_selected_documents(\n        external_id=str(tender.external_id),\n        source_url=tender.source_url,\n        documents=eis_documents,\n    )\n\n    logger.info(\n        "eis_documents_materialized",\n        external_id=tender.external_id,\n        count=len(materialized),\n        names=[\n            document.name\n            for document in materialized\n        ],\n    )\n\n    return materialized\n'}, 'app/sources/gpb/queue_audit.py': {'before': 'a7854c0da2cece94eb1f2e450a1012e9103a15ddf5b92db96263ee5430ede1b2', 'text': '"""Read-only Celery/Redis/GPB backlog audit; never pops, acknowledges or revokes tasks."""\nimport ast\nimport base64\nimport json\nimport sqlite3\nfrom pathlib import Path\nfrom datetime import datetime,timezone\nfrom app.sources.gpb.relevance import screen\n\nLIMIT=10000\nMAX_MESSAGE=16*1024*1024\n\n\ndef decode_message(raw):\n    if isinstance(raw,(bytes,str)):\n        if len(raw)>MAX_MESSAGE:raise ValueError(\'message_size_limit\')\n        raw=json.loads(raw)\n    # Kombu Redis unacked hash stores [message, exchange, routing_key].\n    if isinstance(raw,list) and len(raw)==3 and isinstance(raw[0],dict):raw=raw[0]\n    if not isinstance(raw,dict):raise ValueError(\'unknown_envelope\')\n    h=raw.get(\'headers\') or {}\n    if raw.get(\'content-type\')!=\'application/json\' or h.get(\'compression\'):\n        raise ValueError(\'unsupported_encoding\')\n    body=raw.get(\'body\')\n    if (raw.get(\'properties\') or {}).get(\'body_encoding\')==\'base64\':\n        body=base64.b64decode(body,validate=True)\n    if isinstance(body,(str,bytes)):\n        if len(body)>MAX_MESSAGE:raise ValueError(\'body_size_limit\')\n        body=json.loads(body)\n    if isinstance(body,list) and len(body)>=2:\n        args,kwargs=body[:2]\n    elif isinstance(body,dict):\n        args,kwargs=body.get(\'args\',[]),body.get(\'kwargs\',{})\n    else:raise ValueError(\'unknown_body\')\n    return {\'id\':h.get(\'id\') or raw.get(\'id\'),\'name\':h.get(\'task\') or raw.get(\'task\'),\'args\':args,\'kwargs\':kwargs}\n\n\ndef arguments(value,default):\n    if isinstance(value,str):\n        if len(value)>MAX_MESSAGE:return default\n        try:return ast.literal_eval(value)\n        except (ValueError,SyntaxError,MemoryError,RecursionError):return default\n    return value if isinstance(value,type(default)) or isinstance(value,tuple) else default\n\n\ndef identify(task,by_id,by_external):\n    name=str(task.get(\'name\') or task.get(\'type\') or \'\')\n    args=arguments(task.get(\'args\',[]),[]);kwargs=arguments(task.get(\'kwargs\',{}),{})\n    if not isinstance(kwargs,dict):kwargs={}\n    first=args[0] if args else None\n    incoming=kwargs.get(\'tender_data\',first)\n    if isinstance(incoming,dict) and incoming.get(\'source\')==\'gpb\':\n        return incoming\n    tid=kwargs.get(\'tender_id\')\n    if tid is None and isinstance(first,str) and name.endswith((\'.analyze_tender\',\'.process_tender_documents\')):tid=first\n    if tid is not None:return by_id.get(str(tid))\n    rec=kwargs.get(\'record\',first)\n    if isinstance(rec,dict) and rec.get(\'source\')==\'gpb\':\n        return by_external.get(str(rec.get(\'external_id\'))) or rec\n    return None\n\n\ndef audit():\n    from sqlalchemy import select\n    from app.core.config import settings\n    from app.db.session import SyncSessionLocal\n    from app.models.database import Tender\n    from app.workers.celery_app import celery_app\n    output={\'checked_at\':datetime.now(timezone.utc).isoformat(),\'read_only\':True,\n            \'tasks\':[],\'workers\':{},\'broker\':{},\'backlog\':{},\'errors\':[]}\n    by_id={};by_external={}\n    try:\n        with SyncSessionLocal() as session:\n            rows=session.execute(select(Tender).where(Tender.source==\'gpb\').limit(LIMIT+1)).scalars().all()\n            output[\'db_mapping_complete\']=len(rows)<=LIMIT\n            for t in rows[:LIMIT]:\n                item={\'source\':\'gpb\',\'external_id\':str(t.external_id),\'title\':t.title,\'raw_payload\':t.raw_payload or {},\n                      \'tender_id\':str(t.id),\'analysis_done\':bool(t.analysis_done)}\n                by_id[str(t.id)]=item;by_external[str(t.external_id)]=item\n    except Exception as exc:\n        output[\'errors\'].append({\'phase\':\'db_mapping\',\'type\':type(exc).__name__})\n        output[\'db_mapping_complete\']=False\n    output[\'db_non_target\']=[{\'external_id\':i[\'external_id\'],\'title\':i[\'title\'],\'analysis_done\':i[\'analysis_done\']} for i in by_id.values() if screen(i)[\'action\']==\'reject\']\n    output[\'db_held_unconfirmed\']=[{\'external_id\':i[\'external_id\'],\'title\':i[\'title\'],\'analysis_done\':i[\'analysis_done\']} for i in by_id.values() if screen(i)[\'action\']==\'hold\']\n    seen=set();unmapped=0\n    def append(task,state):\n        nonlocal unmapped\n        item=identify(task,by_id,by_external)\n        name=str(task.get(\'name\') or task.get(\'type\') or \'\')\n        if item is None:\n            if name.endswith((\'.analyze_tender\',\'.process_tender_documents\')):unmapped+=1\n            return\n        key=(str(task.get(\'id\')),state)\n        if key in seen:return\n        seen.add(key)\n        result=screen(item)\n        output[\'tasks\'].append({\'task_id\':task.get(\'id\'),\'task\':name,\'state\':state,\n            \'external_id\':item.get(\'external_id\'),\'title\':item.get(\'title\'),\n            \'llm_task\':name.endswith(\'.analyze_tender\'),\'classification\':result[\'classification\'],\n            \'blocked_by_new_filter\':result[\'action\']!=\'review\'})\n    names=set()\n    for method in (\'active\',\'reserved\',\'scheduled\',\'active_queues\'):\n        try:\n            data=getattr(celery_app.control.inspect(timeout=8),method)()\n            output[\'workers\'][method]=\'no_response\' if data is None else {k:len(v or []) for k,v in data.items()}\n            for worker,items in (data or {}).items():\n                for item in items or []:\n                    if method==\'active_queues\':\n                        if item.get(\'name\'):names.add(item[\'name\'])\n                    else:append(item.get(\'request\',item),method+\':\'+worker)\n        except Exception as exc:output[\'errors\'].append({\'phase\':method,\'type\':type(exc).__name__})\n    try:\n        with celery_app.connection_for_read() as conn:\n            conn.ensure_connection(max_retries=0)\n            channel=conn.channel()\n            try:\n                if conn.transport.driver_type!=\'redis\':raise ValueError(\'unsupported_broker\')\n                client=channel.client\n                names.update(celery_app.amqp.queues.keys())\n                names.add(celery_app.conf.task_default_queue or \'celery\')\n                names.add(\'discovery\')\n                scanned=0;unknown=0;remaining=0\n                for name in sorted(names):\n                    for priority in channel.priority_steps:\n                        key=channel._q_for_pri(name,priority)\n                        count=client.llen(key);take=min(count,max(0,LIMIT-scanned));remaining+=count-take\n                        for start in range(0,take,50):\n                            for raw in client.lrange(key,start,min(start+49,take-1)):\n                                scanned+=1\n                                try:append(decode_message(raw),\'broker_ready:\'+name)\n                                except (ValueError,TypeError,KeyError):unknown+=1\n                unacked=0\n                for _,raw in client.hscan_iter(channel.unacked_key,count=100):\n                    if unacked>=LIMIT:remaining+=1;break\n                    unacked+=1\n                    try:append(decode_message(raw),\'broker_unacked\')\n                    except (ValueError,TypeError,KeyError):unknown+=1\n                output[\'broker\']={\'ready_scanned\':scanned,\'unacked_scanned\':unacked,\'unread_at_least\':remaining,\n                    \'unparsed\':unknown,\'complete\':remaining==0 and unknown==0,\n                    \'note\':\'Snapshot; messages can move during collection. unacked includes reserved and active.\'}\n            finally:channel.close()\n    except Exception as exc:\n        output[\'broker\']={\'complete\':False,\'error_type\':type(exc).__name__}\n    p=Path(settings.storage_path)/\'gpb_backlog.sqlite3\'\n    if p.exists():\n        try:\n            with sqlite3.connect(p.resolve().as_uri()+\'?mode=ro\',uri=True,timeout=5) as db:\n                total=db.execute(\'SELECT COUNT(*) FROM pending\').fetchone()[0]\n                rows=db.execute(\'SELECT payload FROM pending LIMIT ?\', (LIMIT,)).fetchall()\n            rejected=[];held=[]\n            for (payload,) in rows:\n                item=json.loads(payload)\n                decision=screen(item)\n                brief={\'external_id\':item.get(\'external_id\'),\'title\':item.get(\'title\')}\n                if decision[\'action\']==\'reject\':rejected.append(brief)\n                elif decision[\'action\']==\'hold\':held.append(brief)\n            output[\'backlog\']={\'total\':total,\'checked\':len(rows),\'complete\':total<=LIMIT,\'non_target\':rejected,\'held_unconfirmed\':held}\n        except Exception as exc:output[\'backlog\']={\'complete\':False,\'error_type\':type(exc).__name__}\n    else:output[\'backlog\']={\'total\':0,\'complete\':True}\n    output[\'unmapped_processing_messages\']=unmapped\n    output[\'note\']=\'No tasks revoked, no queues purged, no DB changes. Running LLM calls are not interrupted.\'\n    print(json.dumps(output,ensure_ascii=False,indent=2,default=str),flush=True)\n    return output\n\nif __name__==\'__main__\':audit()\n'}}
TESTS = "import json,tempfile,sqlite3\nfrom pathlib import Path\nfrom datetime import datetime,timezone,timedelta\nfrom types import SimpleNamespace\nfrom unittest.mock import patch\nfrom app.sources.gpb.relevance import screen,blocked_item\nfrom app.sources.gpb.queue_audit import decode_message,identify\nfrom app.sources.eis_freshness import gate_saved_tender\nfrom app.reports.gpb_dashboard import candidates_from_file\nfrom app.sources.tektorg.backlog import process_backlog\nfrom app.sources.gpb.dispatch import enqueue_candidates\ncases={\n'Стулья':'reject','Кресло офисное':'reject','Профиль стальной 09Г2С':'reject',\n'Поставка листов нержавеющей стали':'reject','Машина листогибочная трехвалковая':'reject',\n'Стул с алюминиевым профилем':'reject',\n'Материалы для ЭХЗ':'hold','Профиль':'hold','Листовой прокат':'hold',\n'Поставка оборудования':'hold','Прочие изделия':'hold',\n'Алюминиевый профиль АД31':'review','Поставка листов АМг6':'review',\n'Труба алюминиевая':'review','Фольга алюминиевая':'review',\n'Стальные трубы и лист алюминиевый':'review'}\nfor title,want in cases.items():assert screen({'title':title})['action']==want,(title,want)\nassert screen({'title':'Прочие материалы','raw_payload':{'positions':[{'name':'Лист алюминиевый АМг2'}]}})['action']=='review'\nassert screen({'title':'Стулья','raw_payload':{'positions':[{}]}})['action']=='hold'\nassert blocked_item({'source':'gpb','title':'Профиль'})['reason']=='gpb_product_unconfirmed'\nassert blocked_item({'source':'other','title':'Профиль'}) is None\nobj=SimpleNamespace(source='gpb',external_id='1',title='Профиль',id='x',raw_payload={})\nclass Session:\n def get(self,*a):return obj\n def commit(self):raise AssertionError('DB write')\nassert gate_saved_tender(Session(),'x')['reason']=='gpb_product_unconfirmed'\nend=(datetime.now(timezone.utc)+timedelta(days=2)).isoformat()\nitems=[{'source':'gpb','external_id':str(i),'source_url':f'https://etpgpb.ru/procedures/price_request/{i}-test/','title':title,'submission_deadline':end} for i,title in enumerate(['Профиль','Стулья','Алюминиевый профиль АД31'],100)]\n# Actual dispatcher: held and rejected subjects never resolve/download/queue.\nclass Query:\n def scalar_one_or_none(self):return None\nclass DB:\n def __enter__(self):return self\n def __exit__(self,*a):pass\n def execute(self,*a):return Query()\nwith patch('redis.Redis.from_url') as redis, patch('app.db.session.SyncSessionLocal',return_value=DB()), patch('app.sources.gpb.dispatch.is_dismissed',return_value=False),patch('app.sources.gpb.dispatch.resolve') as resolve,patch('app.workers.tasks_parsing.process_new_tender.delay') as delay:\n results=enqueue_candidates(items[:2])\n assert [x['status'] for x in results]==['awaiting_product_confirmation','no_longer_eligible']\n resolve.assert_not_called();delay.assert_not_called();redis.return_value.set.assert_not_called()\nwith tempfile.TemporaryDirectory() as td:\n path=Path(td)/'pending.sqlite3'\n def enqueue(rows):\n  return [{'number':x['external_id'],'status':{'hold':'awaiting_product_confirmation','reject':'no_longer_eligible','review':'batch_limit'}[screen(x)['action']]} for x in rows]\n process_backlog(items,path=path,enqueue=enqueue)\n with sqlite3.connect(path) as db:assert db.execute('SELECT COUNT(*) FROM pending').fetchone()[0]==2\n assert [x['external_id'] for x in candidates_from_file(path)]==['102']\n # Reading the catalog must not delete the held candidate.\n with sqlite3.connect(path) as db:assert db.execute('SELECT COUNT(*) FROM pending').fetchone()[0]==2\nprint('GPB_POSITIVE_TESTS_OK: 16 titles, position evidence, queued-task guard, no handoff for held subjects, internal retention and catalog hiding')\n"
import argparse,hashlib,json,os,shutil,subprocess,sys,tempfile
from pathlib import Path
from datetime import datetime,timezone

def prepare(root):
    changes={}
    for rel,entry in FILES.items():
        p=root/rel
        if not p.is_file():raise SystemExit('DEPENDENCY_MISSING: '+rel)
        old=p.read_text()
        if old==entry['text']:continue
        if hashlib.sha256(p.read_bytes()).hexdigest()!=entry['before']:
            raise SystemExit('VERSION_CONFLICT: '+rel+'; no changes made')
        compile(entry['text'],rel,'exec');changes[rel]=entry['text']
    for rel,marker in [
        ('app/sources/eis_freshness.py','subject_block = blocked_tender(tender)'),
        ('app/workers/tasks_parsing.py','subject_block = blocked_item(source_tender.model_dump())'),
        ('app/workers/tasks_scoring.py','gate_saved_tender('),
        ('app/workers/tasks_ocr.py','gate_saved_tender('),
        ('app/marketplace_discovery/primary/gpb_search.py',"if decision['action'] == 'reject':")]:
        if marker not in (root/rel).read_text():raise SystemExit('PREVIOUS_FILTER_REQUIRED: '+rel)
    return changes

def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check',action='store_true',help='Check compatibility; no changes')
    parser.add_argument('--files-only',action='store_true',help='Development: do not build/restart containers')
    args=parser.parse_args();root=Path.cwd()
    changes=prepare(root)
    print('FILES_TO_UPDATE:',len(changes),flush=True)
    if args.check:return
    if changes:
        backup=Path(tempfile.mkdtemp(prefix='gpb-positive-backup-',dir=root.parent))
        manifest={}
        for rel,text in changes.items():
            p=root/rel;manifest[rel]={'existed':p.exists(),'after_sha256':hashlib.sha256(text.encode()).hexdigest()}
            if p.exists():
                dest=backup/rel;dest.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(p,dest)
        (backup/'restore.json').write_text(json.dumps(manifest,indent=2))
        print('BACKUP:',backup,flush=True)
        written=[]
        try:
            for rel,text in changes.items():
                p=root/rel;p.parent.mkdir(parents=True,exist_ok=True)
                fd,tmp=tempfile.mkstemp(dir=p.parent)
                try:
                    with os.fdopen(fd,'w') as f:f.write(text)
                    os.chmod(tmp,p.stat().st_mode & 0o777 if p.exists() else 0o644)
                    os.replace(tmp,p);written.append(rel)
                finally:
                    if os.path.exists(tmp):os.unlink(tmp)
        except Exception:
            for rel in reversed(written):
                if manifest[rel]['existed']:shutil.copy2(backup/rel,root/rel)
                else:(root/rel).unlink(missing_ok=True)
            raise
    if args.files_only:
        print('FILES_ONLY: containers were NOT updated');return
    subprocess.run(['docker','compose','build','app','celery_worker','celery_discovery'],check=True)
    subprocess.run(['docker','compose','run','--rm','--no-deps','-T','celery_discovery','python','-'],input=TESTS,text=True,check=True)
    # Celery warm shutdown: no forced timeout and no SIGKILL of running tasks.
    ids=subprocess.check_output(['docker','compose','ps','-q','celery_worker','celery_discovery'],text=True).split()
    if ids:
        print('Waiting for Celery warm shutdown; running tasks may take time.',flush=True)
        subprocess.run(['docker','kill','--signal=SIGTERM',*ids],check=True)
        subprocess.run(['docker','wait',*ids],check=True)
    subprocess.run(['docker','compose','up','-d','--no-deps','app','celery_worker','celery_discovery'],check=True)
    print('GPB_POSITIVE_GATE_INSTALLED',flush=True)
    print('QUEUE_AUDIT_BEGIN: read-only snapshot; no collection or analysis started',flush=True)
    audit=subprocess.run(['docker','compose','exec','-T','celery_discovery','python','-m','app.sources.gpb.queue_audit'],stdout=subprocess.PIPE,text=True)
    print(audit.stdout,flush=True)
    stamp=datetime.now(timezone.utc).strftime('%Y%m%d-%H%M%S')
    report=root/('gpb-queue-audit-'+stamp+'.log');report.write_text(audit.stdout)
    print('QUEUE_AUDIT_REPORT:',report,flush=True)
    if audit.returncode:raise SystemExit('FILTER_INSTALLED_BUT_QUEUE_AUDIT_FAILED; queue state unknown')
    print('No business tasks queued/revoked, no queues purged, no DB edits. Existing analysis history retained.')

if __name__=='__main__':main()
